'use strict';

const stripe = require('../testUtils.js').getSpyableStripe();

const expect = require('chai').expect;
const URL = require('url');

describe('OAuth', () => {
  describe('authorize', () => {
    describe('when a default client_id is set', () => {
      beforeEach(() => {
        stripe.setClientId('default_client_id');
      });

      it('Uses the correct host', () => {
        const url = stripe.oauth.authorizeUrl();

        const host = URL.parse(url).hostname;

        expect(host).to.equal('connect.stripe.com');
      });

      it('Uses the correct path', () => {
        const url = stripe.oauth.authorizeUrl({state: 'some_state'});

        const pathname = URL.parse(url).pathname;

        expect(pathname).to.equal('/oauth/authorize');
      });

      it('Uses the correct query', () => {
        const url = stripe.oauth.authorizeUrl({state: 'some_state'});

        const query = Object.fromEntries(
          new URLSearchParams(URL.parse(url).query)
        );

        expect(query.client_id).to.equal('default_client_id');
        expect(query.response_type).to.equal('code');
        expect(query.scope).to.equal('read_write');
        expect(query.state).to.equal('some_state');
      });

      it('Uses a provided client_id instead of the default', () => {
        const url = stripe.oauth.authorizeUrl({client_id: '123abc'});

        const query = Object.fromEntries(
          new URLSearchParams(URL.parse(url).query)
        );

        expect(query.client_id).to.equal('123abc');
      });

      describe('for Express account', () => {
        it('Uses the correct path', () => {
          const url = stripe.oauth.authorizeUrl({}, {express: true});

          const pathname = URL.parse(url).pathname;

          expect(pathname).to.equal('/express/oauth/authorize');
        });
      });
    });
  });

  describe('token', () => {
    it('Sends the correct request', () => {
      stripe.oauth.token({
        code: '123abc',
        grant_type: 'authorization_code',
      });

      expect(stripe.LAST_REQUEST).to.deep.equal({
        method: 'POST',
        host: 'connect.stripe.com',
        url: '/oauth/token',
        headers: {},
        data: {
          code: '123abc',
          grant_type: 'authorization_code',
        },
        settings: {},
      });
    });
  });

  describe('deauthorize', () => {
    beforeEach(() => {
      stripe.setClientId('default_client_id');
    });

    it('Sends the correct request without explicit client_id', () => {
      stripe.oauth.deauthorize({
        stripe_user_id: 'some_user_id',
      });

      expect(stripe.LAST_REQUEST).to.deep.equal({
        method: 'POST',
        host: 'connect.stripe.com',
        url: '/oauth/deauthorize',
        headers: {},
        data: {
          client_id: stripe.getClientId(),
          stripe_user_id: 'some_user_id',
        },
        settings: {},
      });
    });

    it('Sends the correct request with explicit client_id', () => {
      stripe.oauth.deauthorize({
        stripe_user_id: 'some_user_id',
        client_id: '123abc',
      });

      expect(stripe.LAST_REQUEST).to.deep.equal({
        method: 'POST',
        host: 'connect.stripe.com',
        url: '/oauth/deauthorize',
        headers: {},
        data: {
          client_id: '123abc',
          stripe_user_id: 'some_user_id',
        },
        settings: {},
      });
    });
  });
});

// @ts-nocheck
import {Decimal} from '../src/Decimal.js';
import {coerceV2RequestData, coerceV2ResponseData} from '../src/V2Coercion.js';
import {V2RuntimeSchema} from '../src/Types.js';
import {expect} from 'chai';

describe('V2Decimal (via coerceV2RequestData / coerceV2ResponseData)', () => {
  describe('coerceV2ResponseData', () => {
    describe('decimal_string leaf', () => {
      const schema: V2RuntimeSchema = {kind: 'decimal_string'};

      it('converts a string to a Decimal instance', () => {
        const result = coerceV2ResponseData('99.999', schema);
        expect(result).to.be.an.instanceof(Object);
        expect((result as Decimal).toString()).to.equal('99.999');
      });

      it('preserves precision (no float conversion)', () => {
        const result = coerceV2ResponseData('0.1', schema) as Decimal;
        const result2 = coerceV2ResponseData('0.2', schema) as Decimal;
        const sum = result.add(result2);
        expect(sum.toString()).to.equal('0.3');
      });

      it('returns a Decimal that serializes back to the original string', () => {
        const original = '12345678901234567890.1234567890123456789';
        const result = coerceV2ResponseData(original, schema) as Decimal;
        expect(result.toString()).to.equal(original);
      });

      it('passes through null unchanged', () => {
        const result = coerceV2ResponseData(null, schema);
        expect(result).to.be.null;
      });

      it('passes through undefined unchanged', () => {
        const result = coerceV2ResponseData(undefined, schema);
        expect(result).to.be.undefined;
      });

      it('passes through non-string values unchanged', () => {
        expect(coerceV2ResponseData(42, schema)).to.equal(42);
        expect(coerceV2ResponseData(true, schema)).to.equal(true);
      });
    });

    describe('nullable wrapping decimal_string', () => {
      const schema: V2RuntimeSchema = {
        kind: 'nullable',
        inner: {kind: 'decimal_string'},
      };

      it('converts a non-null string to Decimal', () => {
        const result = coerceV2ResponseData('99.999', schema) as Decimal;
        expect(result.toString()).to.equal('99.999');
      });

      it('passes through null unchanged', () => {
        expect(coerceV2ResponseData(null, schema)).to.be.null;
      });
    });

    describe('array of decimal_string', () => {
      const schema: V2RuntimeSchema = {
        kind: 'array',
        element: {kind: 'decimal_string'},
      };

      it('converts each array element to Decimal', () => {
        const data = ['1.0', '2.5', '3.14'];
        const result = coerceV2ResponseData(data, schema) as Decimal[];
        expect(result).to.have.length(3);
        expect(result[0].toString()).to.equal('1');
        expect(result[1].toString()).to.equal('2.5');
        expect(result[2].toString()).to.equal('3.14');
      });

      it('returns empty array unchanged', () => {
        const data: string[] = [];
        const result = coerceV2ResponseData(data, schema);
        expect(result).to.deep.equal([]);
      });

      it('passes through non-array values unchanged', () => {
        expect(coerceV2ResponseData('1.0', schema)).to.equal('1.0');
      });
    });

    describe('object with decimal_string fields', () => {
      const schema: V2RuntimeSchema = {
        kind: 'object',
        fields: {
          amount: {kind: 'decimal_string'},
        },
      };

      it('converts only decimal_string fields', () => {
        const input = {amount: '99.999', name: 'test', extra: 'ignored'};
        const result = coerceV2ResponseData(input, schema) as any;
        expect((result.amount as Decimal).toString()).to.equal('99.999');
        expect(result.name).to.equal('test');
        expect(result.extra).to.equal('ignored');
      });

      it('leaves fields not in schema unchanged', () => {
        const input = {amount: '1.5', unrelated: 'foo'};
        const result = coerceV2ResponseData(input, {
          kind: 'object',
          fields: {amount: {kind: 'decimal_string'}},
        }) as any;
        expect((result.amount as Decimal).toString()).to.equal('1.5');
        expect(result.unrelated).to.equal('foo');
      });

      it('handles missing fields gracefully', () => {
        const input = {extra: 'only'};
        const result = coerceV2ResponseData(input, schema) as any;
        expect(result.extra).to.equal('only');
        expect(result.amount).to.be.undefined;
      });

      it('passes through non-object values unchanged', () => {
        expect(coerceV2ResponseData('string', schema)).to.equal('string');
        expect(coerceV2ResponseData(42, schema)).to.equal(42);
      });
    });

    describe('nested object with decimal_string', () => {
      const schema: V2RuntimeSchema = {
        kind: 'object',
        fields: {
          pricing: {
            kind: 'object',
            fields: {
              unit_amount: {kind: 'decimal_string'},
            },
          },
          label: {kind: 'decimal_string'},
        },
      };

      it('recursively converts nested decimal_string fields', () => {
        const input = {
          pricing: {unit_amount: '99.99', currency: 'usd'},
          label: '1.5',
          id: 'abc',
        };
        const result = coerceV2ResponseData(input, schema) as any;
        expect((result.pricing.unit_amount as Decimal).toString()).to.equal(
          '99.99'
        );
        expect(result.pricing.currency).to.equal('usd');
        expect((result.label as Decimal).toString()).to.equal('1.5');
        expect(result.id).to.equal('abc');
      });
    });

    describe('int64_string non-regression', () => {
      const schema: V2RuntimeSchema = {kind: 'int64_string'};

      it('still converts int64_string strings to bigint', () => {
        expect(coerceV2ResponseData('9007199254740993', schema)).to.equal(
          9007199254740993n
        );
      });

      it('still converts zero int64_string to bigint', () => {
        expect(coerceV2ResponseData('0', schema)).to.equal(0n);
      });
    });
  });

  describe('coerceV2RequestData', () => {
    describe('decimal_string leaf', () => {
      const schema: V2RuntimeSchema = {kind: 'decimal_string'};

      it('converts a Decimal instance to its string form', () => {
        const decimal = Decimal.from('99.999');
        const result = coerceV2RequestData(decimal, schema);
        expect(result).to.equal('99.999');
      });

      it('serializes Decimal.zero as "0"', () => {
        const result = coerceV2RequestData(Decimal.zero, schema);
        expect(result).to.equal('0');
      });

      it('preserves the full precision string', () => {
        const decimal = Decimal.from(
          '12345678901234567890.1234567890123456789'
        );
        const result = coerceV2RequestData(decimal, schema);
        expect(result).to.equal('12345678901234567890.1234567890123456789');
      });

      it('passes through a plain string unchanged', () => {
        // Plain strings don't have Decimal methods, so they pass through
        const result = coerceV2RequestData('99.999', schema);
        expect(result).to.equal('99.999');
      });

      it('passes through null unchanged', () => {
        expect(coerceV2RequestData(null, schema)).to.be.null;
      });

      it('passes through undefined unchanged', () => {
        expect(coerceV2RequestData(undefined, schema)).to.be.undefined;
      });
    });

    describe('nullable wrapping decimal_string', () => {
      const schema: V2RuntimeSchema = {
        kind: 'nullable',
        inner: {kind: 'decimal_string'},
      };

      it('converts a Decimal to string', () => {
        const result = coerceV2RequestData(Decimal.from('99.999'), schema);
        expect(result).to.equal('99.999');
      });

      it('passes through null unchanged', () => {
        expect(coerceV2RequestData(null, schema)).to.be.null;
      });
    });

    describe('array of decimal_string', () => {
      const schema: V2RuntimeSchema = {
        kind: 'array',
        element: {kind: 'decimal_string'},
      };

      it('converts each Decimal element to a string', () => {
        const input = [
          Decimal.from('1.0'),
          Decimal.from('2.5'),
          Decimal.from('3.14'),
        ];
        const result = coerceV2RequestData(input, schema) as string[];
        expect(result).to.deep.equal(['1', '2.5', '3.14']);
      });
    });

    describe('object with decimal_string fields', () => {
      const schema: V2RuntimeSchema = {
        kind: 'object',
        fields: {
          amount: {kind: 'decimal_string'},
        },
      };

      it('converts only decimal_string fields', () => {
        const input = {
          amount: Decimal.from('99.999'),
          name: 'test',
          count: 5,
        };
        const result = coerceV2RequestData(input, schema) as any;
        expect(result.amount).to.equal('99.999');
        expect(result.name).to.equal('test');
        expect(result.count).to.equal(5);
      });

      it('leaves fields not in the schema unchanged', () => {
        const input = {amount: Decimal.from('1.5'), extra: 'ignored'};
        const result = coerceV2RequestData(input, schema) as any;
        expect(result.amount).to.equal('1.5');
        expect(result.extra).to.equal('ignored');
      });
    });

    describe('nested object with decimal_string', () => {
      const schema: V2RuntimeSchema = {
        kind: 'object',
        fields: {
          pricing: {
            kind: 'object',
            fields: {
              unit_amount: {kind: 'decimal_string'},
            },
          },
        },
      };

      it('recursively converts nested Decimal fields to strings', () => {
        const input = {
          pricing: {unit_amount: Decimal.from('99.99'), currency: 'usd'},
          id: 'abc',
        };
        const result = coerceV2RequestData(input, schema) as any;
        expect(result.pricing.unit_amount).to.equal('99.99');
        expect(result.pricing.currency).to.equal('usd');
        expect(result.id).to.equal('abc');
      });
    });

    describe('int64_string non-regression', () => {
      const schema: V2RuntimeSchema = {kind: 'int64_string'};

      it('still converts bigint to string', () => {
        expect(coerceV2RequestData(9007199254740993n, schema)).to.equal(
          '9007199254740993'
        );
      });

      it('still converts number to string', () => {
        expect(coerceV2RequestData(42, schema)).to.equal('42');
      });
    });

    describe('round-trip: serialize then deserialize', () => {
      it('preserves precision through request encoding and response decoding', () => {
        const original = Decimal.from('99.999');
        const schema: V2RuntimeSchema = {kind: 'decimal_string'};

        // Serialize (request encoding)
        const serialized = coerceV2RequestData(original, schema);
        expect(serialized).to.equal('99.999');
        expect(typeof serialized).to.equal('string');

        // Deserialize (response decoding)
        const deserialized = coerceV2ResponseData(
          serialized as string,
          schema
        ) as Decimal;
        expect(deserialized.toString()).to.equal('99.999');
        expect(deserialized.eq(original)).to.equal(true);
      });

      it('round-trips a complex object with decimal fields', () => {
        const requestSchema: V2RuntimeSchema = {
          kind: 'object',
          fields: {
            unit_amount: {kind: 'decimal_string'},
            tax_rate: {kind: 'decimal_string'},
          },
        };

        const originalRequest = {
          unit_amount: Decimal.from('19.99'),
          tax_rate: Decimal.from('0.0825'),
          currency: 'usd',
        };

        // Encode for the wire
        const encoded = coerceV2RequestData(
          originalRequest,
          requestSchema
        ) as any;
        expect(encoded.unit_amount).to.equal('19.99');
        expect(encoded.tax_rate).to.equal('0.0825');
        expect(encoded.currency).to.equal('usd');

        // Simulate receiving a response with the same structure
        const apiResponse = {
          unit_amount: '19.99',
          tax_rate: '0.0825',
          currency: 'usd',
        };
        const decoded = coerceV2ResponseData(apiResponse, requestSchema) as any;
        expect((decoded.unit_amount as Decimal).toString()).to.equal('19.99');
        expect((decoded.tax_rate as Decimal).toString()).to.equal('0.0825');
        expect(decoded.currency).to.equal('usd');
      });
    });
  });
});

// @ts-nocheck
import {expect} from 'chai';
import {Decimal} from '../src/Decimal.js';
import {StripeResource} from '../src/StripeResource.js';
import {getSpyableStripe} from './testUtils.js';

describe('V2 decimal_string integration', () => {
  const requestSchema = {
    kind: 'object',
    fields: {
      lines: {
        kind: 'array',
        element: {
          kind: 'object',
          fields: {
            unit_amount_decimal: {kind: 'decimal_string'},
          },
        },
      },
    },
  };

  const makeRequest = (method: string) => {
    const stripe = getSpyableStripe();
    const resource = new StripeResource(stripe);

    resource._makeRequest(
      method,
      '/v2/test/resources',
      {
        lines: [
          {
            unit_amount_decimal: Decimal.from('434'),
            description: 'test',
          },
        ],
      },
      undefined,
      {requestSchema}
    );

    return stripe.LAST_REQUEST;
  };

  it('coerces nested decimal_string fields in GET query parameters', () => {
    const request = makeRequest('GET');

    expect(request.data).to.equal(null);
    expect(request.url).to.equal(
      '/v2/test/resources?lines[0][unit_amount_decimal]=434&lines[0][description]=test'
    );
  });

  it('coerces nested decimal_string fields in DELETE query parameters', () => {
    const request = makeRequest('DELETE');

    expect(request.data).to.equal(null);
    expect(request.url).to.equal(
      '/v2/test/resources?lines[0][unit_amount_decimal]=434&lines[0][description]=test'
    );
  });

  it('continues to coerce nested decimal_string fields in POST bodies', () => {
    const request = makeRequest('POST');

    expect(request.data).to.deep.equal({
      lines: [{unit_amount_decimal: '434', description: 'test'}],
    });
    expect(request.url).to.equal('/v2/test/resources');
  });
});

// @ts-nocheck
import {Decimal} from '../src/Decimal.js';
import {expect} from 'chai';

describe('Decimal', () => {
  describe('Decimal.from(string)', () => {
    it('parses integer strings', () => {
      expect(Decimal.from('42').toString()).to.equal('42');
      expect(Decimal.from('0').toString()).to.equal('0');
      expect(Decimal.from('-42').toString()).to.equal('-42');
    });

    it('parses decimal strings', () => {
      expect(Decimal.from('1.23').toString()).to.equal('1.23');
      expect(Decimal.from('0.1').toString()).to.equal('0.1');
      expect(Decimal.from('-0.1').toString()).to.equal('-0.1');
      expect(Decimal.from('123.456').toString()).to.equal('123.456');
    });

    it('parses strings with leading zeros', () => {
      expect(Decimal.from('0.001').toString()).to.equal('0.001');
      expect(Decimal.from('0.00000001').toString()).to.equal('0.00000001');
    });

    it('parses exponential notation', () => {
      expect(Decimal.from('1e3').toString()).to.equal('1000');
      expect(Decimal.from('1.23e2').toString()).to.equal('123');
      expect(Decimal.from('1.23e-2').toString()).to.equal('0.0123');
      expect(Decimal.from('1E+3').toString()).to.equal('1000');
    });

    it('trims whitespace', () => {
      expect(Decimal.from('  42  ').toString()).to.equal('42');
      expect(Decimal.from('\t1.23\n').toString()).to.equal('1.23');
    });

    it('normalizes trailing zeros', () => {
      expect(Decimal.from('1.00').toString()).to.equal('1');
      expect(Decimal.from('1.2300').toString()).to.equal('1.23');
      expect(Decimal.from('100').toString()).to.equal('100');
    });

    it('normalizes negative zero to zero', () => {
      expect(Decimal.from('-0').toString()).to.equal('0');
      expect(Decimal.from('-0.0').toString()).to.equal('0');
      expect(Decimal.from('-0').isZero()).to.equal(true);
    });

    it('normalizes zero with exponent', () => {
      expect(Decimal.from('0e999').toString()).to.equal('0');
      expect(Decimal.from('0.00e5').toString()).to.equal('0');
    });

    it('throws on empty string', () => {
      expect(() => Decimal.from('')).to.throw(
        'Cannot parse empty string as Decimal'
      );
      expect(() => Decimal.from('   ')).to.throw(
        'Cannot parse empty string as Decimal'
      );
    });

    it('throws on invalid format', () => {
      expect(() => Decimal.from('abc')).to.throw('Invalid decimal string');
      expect(() => Decimal.from('1.2.3')).to.throw('Invalid decimal string');
      expect(() => Decimal.from('1..2')).to.throw('Invalid decimal string');
      expect(() => Decimal.from('--1')).to.throw('Invalid decimal string');
    });
  });

  describe('Decimal.from(number)', () => {
    it('converts finite numbers', () => {
      expect(Decimal.from(42).toString()).to.equal('42');
      expect(Decimal.from(1.23).toString()).to.equal('1.23');
      expect(Decimal.from(-0.1).toString()).to.equal('-0.1');
      expect(Decimal.from(0).toString()).to.equal('0');
    });

    it('preserves user intent for 0.1', () => {
      expect(Decimal.from(0.1).toString()).to.equal('0.1');
    });

    it('throws on Infinity', () => {
      expect(() => Decimal.from(Infinity)).to.throw('Number must be finite');
      expect(() => Decimal.from(-Infinity)).to.throw('Number must be finite');
    });

    it('throws on NaN', () => {
      expect(() => Decimal.from(NaN)).to.throw('Number must be finite');
    });
  });

  describe('Decimal.from(bigint)', () => {
    it('converts bigints as integers', () => {
      expect(Decimal.from(42n).toString()).to.equal('42');
      expect(Decimal.from(0n).toString()).to.equal('0');
      expect(Decimal.from(-42n).toString()).to.equal('-42');
      expect(Decimal.from(123456789012345678901234567890n).toString()).to.equal(
        '123456789012345678901234567890'
      );
    });
  });

  describe('Decimal.zero', () => {
    it('is zero', () => {
      expect(Decimal.zero.toString()).to.equal('0');
      expect(Decimal.zero.isZero()).to.equal(true);
    });
  });

  describe('addition', () => {
    it('adds integers', () => {
      expect(
        Decimal.from('42')
          .add(Decimal.from('8'))
          .toString()
      ).to.equal('50');
      expect(
        Decimal.from('100')
          .add(Decimal.from('200'))
          .toString()
      ).to.equal('300');
    });

    it('adds decimals', () => {
      expect(
        Decimal.from('1.2')
          .add(Decimal.from('3.4'))
          .toString()
      ).to.equal('4.6');
      expect(
        Decimal.from('0.1')
          .add(Decimal.from('0.2'))
          .toString()
      ).to.equal('0.3');
    });

    it('adds with different scales', () => {
      expect(
        Decimal.from('1.5')
          .add(Decimal.from('2'))
          .toString()
      ).to.equal('3.5');
      expect(
        Decimal.from('1.23')
          .add(Decimal.from('4.5'))
          .toString()
      ).to.equal('5.73');
    });

    it('handles negative operands', () => {
      expect(
        Decimal.from('-1')
          .add(Decimal.from('2'))
          .toString()
      ).to.equal('1');
      expect(
        Decimal.from('1')
          .add(Decimal.from('-2'))
          .toString()
      ).to.equal('-1');
      expect(
        Decimal.from('-1')
          .add(Decimal.from('-2'))
          .toString()
      ).to.equal('-3');
    });

    it('handles zero', () => {
      expect(
        Decimal.from('42')
          .add(Decimal.zero)
          .toString()
      ).to.equal('42');
      expect(Decimal.zero.add(Decimal.from('42')).toString()).to.equal('42');
    });
  });

  describe('subtraction', () => {
    it('subtracts integers', () => {
      expect(
        Decimal.from('50')
          .sub(Decimal.from('8'))
          .toString()
      ).to.equal('42');
      expect(
        Decimal.from('200')
          .sub(Decimal.from('100'))
          .toString()
      ).to.equal('100');
    });

    it('subtracts decimals', () => {
      expect(
        Decimal.from('5.5')
          .sub(Decimal.from('2.3'))
          .toString()
      ).to.equal('3.2');
      expect(
        Decimal.from('0.3')
          .sub(Decimal.from('0.1'))
          .toString()
      ).to.equal('0.2');
    });

    it('handles negative results', () => {
      expect(
        Decimal.from('1')
          .sub(Decimal.from('2'))
          .toString()
      ).to.equal('-1');
      expect(
        Decimal.from('-1')
          .sub(Decimal.from('2'))
          .toString()
      ).to.equal('-3');
    });

    it('handles zero', () => {
      expect(
        Decimal.from('42')
          .sub(Decimal.zero)
          .toString()
      ).to.equal('42');
      expect(Decimal.zero.sub(Decimal.from('42')).toString()).to.equal('-42');
    });
  });

  describe('multiplication', () => {
    it('multiplies integers', () => {
      expect(
        Decimal.from('6')
          .mul(Decimal.from('7'))
          .toString()
      ).to.equal('42');
      expect(
        Decimal.from('10')
          .mul(Decimal.from('20'))
          .toString()
      ).to.equal('200');
    });

    it('multiplies decimals', () => {
      expect(
        Decimal.from('1.5')
          .mul(Decimal.from('2'))
          .toString()
      ).to.equal('3');
      expect(
        Decimal.from('2.5')
          .mul(Decimal.from('4'))
          .toString()
      ).to.equal('10');
      expect(
        Decimal.from('0.1')
          .mul(Decimal.from('0.2'))
          .toString()
      ).to.equal('0.02');
    });

    it('handles negative operands', () => {
      expect(
        Decimal.from('-6')
          .mul(Decimal.from('7'))
          .toString()
      ).to.equal('-42');
      expect(
        Decimal.from('6')
          .mul(Decimal.from('-7'))
          .toString()
      ).to.equal('-42');
      expect(
        Decimal.from('-6')
          .mul(Decimal.from('-7'))
          .toString()
      ).to.equal('42');
    });

    it('handles zero', () => {
      expect(
        Decimal.from('42')
          .mul(Decimal.zero)
          .toString()
      ).to.equal('0');
      expect(Decimal.zero.mul(Decimal.from('42')).toString()).to.equal('0');
    });
  });

  describe('division', () => {
    it('divides integers evenly', () => {
      expect(
        Decimal.from('42')
          .div(Decimal.from('6'), 34, 'half-up')
          .toString()
      ).to.equal('7');
      expect(
        Decimal.from('100')
          .div(Decimal.from('10'), 34, 'half-up')
          .toString()
      ).to.equal('10');
    });

    it('divides with decimal results', () => {
      const result = Decimal.from('1').div(Decimal.from('3'), 5, 'half-up');
      expect(result.toString()).to.equal('0.33333');
    });

    it('divides with full precision', () => {
      const result = Decimal.from('1').div(Decimal.from('3'), 34, 'half-up');
      const str = result.toString();
      expect(str).to.match(/^0\.3+$/);
    });

    it('handles negative operands', () => {
      expect(
        Decimal.from('-42')
          .div(Decimal.from('6'), 34, 'half-up')
          .toString()
      ).to.equal('-7');
      expect(
        Decimal.from('42')
          .div(Decimal.from('-6'), 34, 'half-up')
          .toString()
      ).to.equal('-7');
      expect(
        Decimal.from('-42')
          .div(Decimal.from('-6'), 34, 'half-up')
          .toString()
      ).to.equal('7');
    });

    it('throws on division by zero', () => {
      expect(() =>
        Decimal.from('42').div(Decimal.zero, 34, 'half-up')
      ).to.throw('Division by zero');
    });

    it('throws on negative precision', () => {
      expect(() =>
        Decimal.from('10').div(Decimal.from('3'), -5, 'half-up')
