    it('throws on non-integer precision', () => {
      expect(() =>
        Decimal.from('10').div(Decimal.from('3'), 2.5, 'half-up')
      ).to.throw('precision must be a non-negative integer');
    });

    it('half-up rounding', () => {
      expect(
        Decimal.from('5')
          .div(Decimal.from('2'), 0, 'half-up')
          .toString()
      ).to.equal('3');
