    describe('eq', () => {
      it('returns true for equal values', () => {
        expect(Decimal.from('42').eq(Decimal.from('42'))).to.equal(true);
        expect(Decimal.from('1.0').eq(Decimal.from('1'))).to.equal(true);
      });

      it('returns false for unequal values', () => {
        expect(Decimal.from('42').eq(Decimal.from('43'))).to.equal(false);
        expect(Decimal.from('1.23').eq(Decimal.from('1.24'))).to.equal(false);
      });
    });

    describe('lt', () => {
      it('returns true when less than', () => {
        expect(Decimal.from('1').lt(Decimal.from('2'))).to.equal(true);
        expect(Decimal.from('-2').lt(Decimal.from('-1'))).to.equal(true);
      });

      it('returns false when equal or greater', () => {
        expect(Decimal.from('2').lt(Decimal.from('2'))).to.equal(false);
        expect(Decimal.from('2').lt(Decimal.from('1'))).to.equal(false);
      });
    });

    describe('lte', () => {
      it('returns true when less than or equal', () => {
        expect(Decimal.from('1').lte(Decimal.from('2'))).to.equal(true);
        expect(Decimal.from('2').lte(Decimal.from('2'))).to.equal(true);
      });

      it('returns false when greater', () => {
        expect(Decimal.from('2').lte(Decimal.from('1'))).to.equal(false);
      });
    });

    describe('gt', () => {
      it('returns true when greater than', () => {
        expect(Decimal.from('2').gt(Decimal.from('1'))).to.equal(true);
        expect(Decimal.from('-1').gt(Decimal.from('-2'))).to.equal(true);
      });

      it('returns false when equal or less', () => {
        expect(Decimal.from('2').gt(Decimal.from('2'))).to.equal(false);
        expect(Decimal.from('1').gt(Decimal.from('2'))).to.equal(false);
      });
    });

    describe('gte', () => {
      it('returns true when greater than or equal', () => {
        expect(Decimal.from('2').gte(Decimal.from('1'))).to.equal(true);
        expect(Decimal.from('2').gte(Decimal.from('2'))).to.equal(true);
      });

      it('returns false when less', () => {
        expect(Decimal.from('1').gte(Decimal.from('2'))).to.equal(false);
      });
    });
  });

  describe('predicates', () => {
    describe('isZero', () => {
      it('returns true for zero', () => {
        expect(Decimal.from('0').isZero()).to.equal(true);
        expect(Decimal.from('0.0').isZero()).to.equal(true);
        expect(Decimal.zero.isZero()).to.equal(true);
      });

      it('returns false for non-zero', () => {
        expect(Decimal.from('1').isZero()).to.equal(false);
        expect(Decimal.from('-1').isZero()).to.equal(false);
        expect(Decimal.from('0.1').isZero()).to.equal(false);
      });
    });

    describe('isNegative', () => {
      it('returns true for negative values', () => {
        expect(Decimal.from('-1').isNegative()).to.equal(true);
        expect(Decimal.from('-0.1').isNegative()).to.equal(true);
      });

      it('returns false for zero and positive values', () => {
        expect(Decimal.from('0').isNegative()).to.equal(false);
        expect(Decimal.from('1').isNegative()).to.equal(false);
      });
    });

    describe('isPositive', () => {
      it('returns true for positive values', () => {
        expect(Decimal.from('1').isPositive()).to.equal(true);
        expect(Decimal.from('0.1').isPositive()).to.equal(true);
      });

      it('returns false for zero and negative values', () => {
        expect(Decimal.from('0').isPositive()).to.equal(false);
        expect(Decimal.from('-1').isPositive()).to.equal(false);
      });
    });
  });

  describe('unary operations', () => {
    describe('neg', () => {
      it('negates positive values', () => {
        expect(
          Decimal.from('42')
            .neg()
            .toString()
        ).to.equal('-42');
        expect(
          Decimal.from('1.23')
            .neg()
            .toString()
        ).to.equal('-1.23');
      });

      it('negates negative values', () => {
        expect(
          Decimal.from('-42')
            .neg()
            .toString()
        ).to.equal('42');
        expect(
          Decimal.from('-1.23')
            .neg()
            .toString()
        ).to.equal('1.23');
      });

      it('negates zero', () => {
        expect(Decimal.zero.neg().toString()).to.equal('0');
      });
    });

    describe('abs', () => {
      it('returns absolute value of negative', () => {
        expect(
          Decimal.from('-42')
            .abs()
            .toString()
        ).to.equal('42');
        expect(
          Decimal.from('-1.23')
            .abs()
            .toString()
        ).to.equal('1.23');
      });

      it('returns same value for positive', () => {
        expect(
          Decimal.from('42')
            .abs()
            .toString()
        ).to.equal('42');
        expect(
          Decimal.from('1.23')
            .abs()
            .toString()
        ).to.equal('1.23');
      });

      it('returns zero for zero', () => {
        expect(Decimal.zero.abs().toString()).to.equal('0');
      });
    });
  });

  describe('toString', () => {
    it('returns plain notation for reasonable values', () => {
      expect(Decimal.from('123').toString()).to.equal('123');
      expect(Decimal.from('1.23').toString()).to.equal('1.23');
      expect(Decimal.from('0.001').toString()).to.equal('0.001');
    });

    it('uses exponential notation for very large values (over 30 digits)', () => {
      const large = Decimal.from('1234567890123456789012345678901');
      expect(large.toString()).to.equal('1.234567890123456789012345678901E+30');
    });

    it('uses single-digit exponential notation for large round numbers', () => {
      expect(Decimal.from('1e40').toString()).to.equal('1E+40');
    });

    it('keeps values at exactly 30 digits in plain notation', () => {
      expect(Decimal.from('1e29').toString()).to.equal('1' + '0'.repeat(29));
    });

    it('handles zero', () => {
      expect(Decimal.zero.toString()).to.equal('0');
    });

    it('strips trailing zeros', () => {
      expect(Decimal.from('1.00').toString()).to.equal('1');
      expect(Decimal.from('1.2300').toString()).to.equal('1.23');
    });
  });

  describe('toJSON', () => {
    it('returns string representation', () => {
      expect(Decimal.from('42').toJSON()).to.equal('42');
      expect(Decimal.from('1.23').toJSON()).to.equal('1.23');
    });

    it('serializes correctly with JSON.stringify', () => {
      const obj = {price: Decimal.from('19.99')};
      expect(JSON.stringify(obj)).to.equal('{"price":"19.99"}');
    });
  });

  describe('toNumber', () => {
    it('converts to JavaScript number', () => {
      expect(Decimal.from('42').toNumber()).to.equal(42);
      expect(Decimal.from('1.23').toNumber()).to.equal(1.23);
      expect(Decimal.from('-42').toNumber()).to.equal(-42);
    });

    it('may lose precision for very large values', () => {
      const large = Decimal.from('99999999999999999999999999999999');
      const asNumber = large.toNumber();
      expect(typeof asNumber).to.equal('number');
      expect(Number.isFinite(asNumber)).to.equal(true);
    });
  });

  describe('toFixed', () => {
    it('formats with specified decimal places', () => {
      expect(Decimal.from('1.23456').toFixed(2, 'half-up')).to.equal('1.23');
      expect(Decimal.from('1.5').toFixed(3, 'half-up')).to.equal('1.500');
      expect(Decimal.from('42').toFixed(0, 'half-up')).to.equal('42');
    });

    it('formats zero with decimal places', () => {
      expect(Decimal.zero.toFixed(5, 'half-up')).to.equal('0.00000');
      expect(Decimal.from('0').toFixed(2, 'half-up')).to.equal('0.00');
      expect(Decimal.zero.toFixed(0, 'half-up')).to.equal('0');
    });

    it('rounds with half-up', () => {
      expect(Decimal.from('1.235').toFixed(2, 'half-up')).to.equal('1.24');
      expect(Decimal.from('1.225').toFixed(2, 'half-up')).to.equal('1.23');
    });

    it('rounds with half-even', () => {
      expect(Decimal.from('1.235').toFixed(2, 'half-even')).to.equal('1.24');
      expect(Decimal.from('1.225').toFixed(2, 'half-even')).to.equal('1.22');
    });

    it('throws on negative decimal places', () => {
      expect(() => Decimal.from('1.23').toFixed(-1, 'half-up')).to.throw(
        'decimalPlaces must be a non-negative integer'
      );
    });

    it('throws on non-integer decimal places', () => {
      expect(() => Decimal.from('1.23').toFixed(1.5, 'half-up')).to.throw(
        'decimalPlaces must be a non-negative integer'
      );
    });
  });

  describe('valueOf', () => {
    it('returns string to prevent precision loss', () => {
      const d = Decimal.from('1.23');
      expect(d.valueOf()).to.equal('1.23');
      expect(typeof d.valueOf()).to.equal('string');
    });

    it('prevents silent conversion to number in arithmetic', () => {
      const d = Decimal.from('0.1');
      const result = (d as any) + (d as any);
      expect(typeof result).to.equal('string');
      expect(result).to.equal('0.10.1');
    });
  });

  describe('immutability', () => {
    it('operations return new instances', () => {
      const a = Decimal.from('1');
      const b = Decimal.from('2');
      const sum = a.add(b);
      expect(a.toString()).to.equal('1');
      expect(b.toString()).to.equal('2');
      expect(sum.toString()).to.equal('3');
    });

    it('instances are frozen', () => {
      const d = Decimal.from('42');
      expect(Object.isFrozen(d)).to.equal(true);
    });
  });

  describe('edge cases', () => {
    it('handles very large numbers', () => {
      const large = Decimal.from('123456789012345678901234567890');
      expect(large.add(Decimal.from('1')).toString()).to.equal(
        '123456789012345678901234567891'
      );
    });

    it('handles very small numbers', () => {
      const small = Decimal.from('0.000000000000000000000000000001');
      expect(small.mul(Decimal.from('2')).toString()).to.equal(
        '0.000000000000000000000000000002'
      );
    });

    it('handles mixed-scale arithmetic', () => {
      const a = Decimal.from('1e10');
      const b = Decimal.from('0.0000000001');
      expect(a.mul(b).toString()).to.equal('1');
    });

    it('normalizes zero from subtraction', () => {
      expect(
        Decimal.from('1')
          .sub(Decimal.from('1'))
          .toString()
      ).to.equal('0');
      expect(
        Decimal.from('1.23')
          .sub(Decimal.from('1.23'))
          .isZero()
      ).to.equal(true);
    });

    it('div does not crash when divisor exponent exceeds dividend exponent plus precision', () => {
      const result = Decimal.from('1').div(Decimal.from('1e100'), 0, 'half-up');
      expect(result.toString()).to.equal('0');
    });

    it('toString uses scientific notation for very small exponents', () => {
      const small = Decimal.from('1e-100');
      const str = small.toString();
      expect(str.length).to.be.lessThan(50);
      expect(str).to.equal('1E-100');
    });

    it('from rejects exponents beyond safe integer range', () => {
      expect(() => Decimal.from('1e99999999999999999')).to.throw();
      expect(() => Decimal.from('1e-99999999999999999')).to.throw();
    });
  });

  describe('billing calculation examples', () => {
    it('calculates invoice total with tax', () => {
      const subtotal = Decimal.from('99.99');
      const taxRate = Decimal.from('0.0825');
      const tax = subtotal.mul(taxRate);
      const total = subtotal.add(tax);

      expect(tax.toFixed(2, 'half-up')).to.equal('8.25');
      expect(total.toFixed(2, 'half-up')).to.equal('108.24');
    });

    it('splits bill evenly', () => {
      const total = Decimal.from('100.00');
      const people = Decimal.from('3');
      const perPerson = total.div(people, 2, 'half-up');
      expect(perPerson.toFixed(2, 'half-up')).to.equal('33.33');
    });

    it('accumulates small amounts without floating-point errors', () => {
      let sum = Decimal.zero;
      for (let i = 0; i < 100; i++) {
        sum = sum.add(Decimal.from('0.01'));
      }
      expect(sum.toString()).to.equal('1');
    });
  });

  describe('classic floating-point pitfalls', () => {
    it('0.1 + 0.2 === 0.3', () => {
      const result = Decimal.from('0.1').add(Decimal.from('0.2'));
      expect(result.eq(Decimal.from('0.3'))).to.equal(true);
      expect(result.toString()).to.equal('0.3');
    });

    it('0.1 + 0.2 - 0.3 === 0', () => {
      const result = Decimal.from('0.1')
        .add(Decimal.from('0.2'))
        .sub(Decimal.from('0.3'));
      expect(result.isZero()).to.equal(true);
    });

    it('0.3 - 0.1 === 0.2', () => {
      expect(
        Decimal.from('0.3')
          .sub(Decimal.from('0.1'))
          .eq(Decimal.from('0.2'))
      ).to.equal(true);
    });

    it('0.1 × 3 === 0.3', () => {
      expect(
        Decimal.from('0.1')
          .mul(Decimal.from('3'))
          .eq(Decimal.from('0.3'))
      ).to.equal(true);
    });
  });

  describe('division rounding edge cases', () => {
    it('half-up: rounds 0.5 up', () => {
      expect(Decimal.from('0.5').toFixed(0, 'half-up')).to.equal('1');
      expect(Decimal.from('1.5').toFixed(0, 'half-up')).to.equal('2');
      expect(Decimal.from('2.5').toFixed(0, 'half-up')).to.equal('3');
    });

    it('half-up: rounds negative 0.5 away from zero', () => {
      expect(Decimal.from('-0.5').toFixed(0, 'half-up')).to.equal('-1');
      expect(Decimal.from('-1.5').toFixed(0, 'half-up')).to.equal('-2');
      expect(Decimal.from('-2.5').toFixed(0, 'half-up')).to.equal('-3');
    });

    it('half-even: rounds 0.5 to even', () => {
      expect(Decimal.from('0.5').toFixed(0, 'half-even')).to.equal('0');
      expect(Decimal.from('1.5').toFixed(0, 'half-even')).to.equal('2');
      expect(Decimal.from('2.5').toFixed(0, 'half-even')).to.equal('2');
      expect(Decimal.from('3.5').toFixed(0, 'half-even')).to.equal('4');
    });

    it('half-even: rounds negative 0.5 to even', () => {
      expect(Decimal.from('-0.5').toFixed(0, 'half-even')).to.equal('0');
      expect(Decimal.from('-1.5').toFixed(0, 'half-even')).to.equal('-2');
      expect(Decimal.from('-2.5').toFixed(0, 'half-even')).to.equal('-2');
      expect(Decimal.from('-3.5').toFixed(0, 'half-even')).to.equal('-4');
    });

    it('division precision does not lose significance', () => {
      const result = Decimal.from('1').div(Decimal.from('7'), 10, 'half-up');
      expect(result.toFixed(10, 'half-up')).to.equal('0.1428571429');
    });
  });
});

// @ts-nocheck
import {expect} from 'chai';
import {coerceV2RequestData, coerceV2ResponseData} from '../src/V2Coercion.js';
import {V2RuntimeSchema} from '../src/Types.js';

describe('V2Int64', () => {
  describe('coerceV2RequestData', () => {
    describe('int64_string kind', () => {
      const schema: V2RuntimeSchema = {kind: 'int64_string'};

      it('converts bigint to string', () => {
        expect(coerceV2RequestData(42n, schema)).to.equal('42');
      });

      it('converts large bigint to string', () => {
        expect(coerceV2RequestData(9007199254740993n, schema)).to.equal(
          '9007199254740993'
        );
      });

      it('converts zero bigint to string', () => {
        expect(coerceV2RequestData(0n, schema)).to.equal('0');
      });

      it('converts negative bigint to string', () => {
        expect(coerceV2RequestData(-100n, schema)).to.equal('-100');
      });

      it('converts number to string as defensive fallback', () => {
        expect(coerceV2RequestData(42, schema)).to.equal('42');
      });

      it('leaves string values unchanged', () => {
        expect(coerceV2RequestData('42', schema)).to.equal('42');
      });

      it('passes null through', () => {
        expect(coerceV2RequestData(null, schema)).to.equal(null);
      });

      it('passes undefined through', () => {
        expect(coerceV2RequestData(undefined, schema)).to.equal(undefined);
      });
    });

    describe('object kind', () => {
      const schema: V2RuntimeSchema = {
        kind: 'object',
        fields: {
          amount: {kind: 'int64_string'},
        },
      };

      it('coerces fields listed in schema', () => {
        const result = coerceV2RequestData({amount: 100n}, schema);
        expect(result).to.deep.equal({amount: '100'});
      });

      it('preserves fields not in schema', () => {
        const result = coerceV2RequestData(
          {amount: 100n, name: 'test'},
          schema
        );
        expect(result).to.deep.equal({amount: '100', name: 'test'});
      });

      it('does not mutate the original object', () => {
        const original = {amount: 100n};
        coerceV2RequestData(original, schema);
        expect(original.amount).to.equal(100n);
      });

      it('passes null through', () => {
        expect(coerceV2RequestData(null, schema)).to.equal(null);
      });

      it('handles non-object gracefully', () => {
        expect(coerceV2RequestData('not an object', schema)).to.equal(
          'not an object'
        );
      });
    });

    describe('nested object kind', () => {
      const schema: V2RuntimeSchema = {
        kind: 'object',
        fields: {
          transform_quantity: {
            kind: 'object',
            fields: {
              divide_by: {kind: 'int64_string'},
            },
          },
        },
      };

      it('coerces nested fields', () => {
        const result = coerceV2RequestData(
          {transform_quantity: {divide_by: 500n}},
          schema
        );
        expect(result).to.deep.equal({
          transform_quantity: {divide_by: '500'},
        });
      });

      it('preserves unrelated nested fields', () => {
        const result = coerceV2RequestData(
          {transform_quantity: {divide_by: 500n, round: 'up'}, name: 'test'},
          schema
        );
        expect(result).to.deep.equal({
          transform_quantity: {divide_by: '500', round: 'up'},
          name: 'test',
        });
      });
    });

    describe('array kind', () => {
      const schema: V2RuntimeSchema = {
        kind: 'array',
        element: {kind: 'int64_string'},
      };

      it('coerces each element', () => {
        const result = coerceV2RequestData([1n, 2n, 3n], schema);
        expect(result).to.deep.equal(['1', '2', '3']);
      });

      it('handles empty array', () => {
        const result = coerceV2RequestData([], schema);
        expect(result).to.deep.equal([]);
      });

      it('passes null through', () => {
        expect(coerceV2RequestData(null, schema)).to.equal(null);
      });

      it('handles non-array gracefully', () => {
        expect(coerceV2RequestData('not an array', schema)).to.equal(
          'not an array'
        );
      });
    });

    describe('array of objects kind', () => {
      const schema: V2RuntimeSchema = {
        kind: 'array',
        element: {
          kind: 'object',
          fields: {
            amount: {kind: 'int64_string'},
          },
        },
      };

      it('coerces fields within array elements', () => {
        const result = coerceV2RequestData(
          [{amount: 100n}, {amount: 200n}],
          schema
        );
        expect(result).to.deep.equal([{amount: '100'}, {amount: '200'}]);
      });
    });

    describe('nullable kind', () => {
      const schema: V2RuntimeSchema = {
        kind: 'nullable',
        inner: {kind: 'int64_string'},
      };

      it('coerces non-null value', () => {
        expect(coerceV2RequestData(42n, schema)).to.equal('42');
      });

      it('passes null through', () => {
        expect(coerceV2RequestData(null, schema)).to.equal(null);
      });

      it('passes undefined through', () => {
        expect(coerceV2RequestData(undefined, schema)).to.equal(undefined);
      });
    });

    describe('discriminatedUnion kind', () => {
      const schema: V2RuntimeSchema = {
        kind: 'discriminatedUnion',
        discriminator: 'type',
        variants: {
          bank_transfer: {
            kind: 'object',
            fields: {
              amount: {kind: 'int64_string'},
            },
          },
          card: {
            kind: 'object',
            fields: {
              fee: {kind: 'int64_string'},
            },
          },
        },
      };

      it('coerces fields in the matched variant', () => {
        const result = coerceV2RequestData(
          {type: 'bank_transfer', amount: 100n},
          schema
        );
        expect(result).to.deep.equal({type: 'bank_transfer', amount: '100'});
      });

      it('coerces a different variant', () => {
        const result = coerceV2RequestData({type: 'card', fee: 250n}, schema);
        expect(result).to.deep.equal({type: 'card', fee: '250'});
      });

      it('returns data unchanged when discriminator value is not in variants', () => {
        const input = {type: 'unknown_type', amount: 100n};
        const result = coerceV2RequestData(input, schema);
        expect(result).to.deep.equal({type: 'unknown_type', amount: 100n});
      });

      it('throws when discriminator field is missing', () => {
        // Skipping coercion here would send `amount` as a raw JSON number and
        // lose precision above Number.MAX_SAFE_INTEGER, with no error.
        expect(() => coerceV2RequestData({amount: 100n}, schema)).to.throw(
          /discriminator `type`/
        );
      });

      it('lists the valid variants when it throws', () => {
        expect(() => coerceV2RequestData({amount: 100n}, schema)).to.throw(
          /bank_transfer, card/
        );
      });

      it('throws when discriminator value is not a string', () => {
        for (const bad of [123, true, {}, [], 1.5, null]) {
          expect(
            () => coerceV2RequestData({type: bad, amount: 100n}, schema),
            `expected ${JSON.stringify(bad)} to be rejected`
          ).to.throw(/discriminator `type`/);
        }
      });

      it('passes null through', () => {
        // An omitted optional union is not a missing discriminator.
        expect(coerceV2RequestData(null, schema)).to.equal(null);
      });

      it('handles non-object gracefully', () => {
        expect(coerceV2RequestData('not an object', schema)).to.equal(
          'not an object'
        );
      });

      it('handles array gracefully', () => {
        const input = [1, 2, 3];
        expect(coerceV2RequestData(input, schema)).to.deep.equal([1, 2, 3]);
      });
    });

    describe('complex schema', () => {
      const schema: V2RuntimeSchema = {
        kind: 'object',
        fields: {
          items: {
            kind: 'array',
            element: {
              kind: 'object',
              fields: {
                quantity: {kind: 'int64_string'},
                metadata: {
                  kind: 'nullable',
                  inner: {
                    kind: 'object',
                    fields: {
                      order_id: {kind: 'int64_string'},
                    },
                  },
                },
              },
            },
          },
        },
      };

      it('coerces deeply nested int64_string fields', () => {
        const input = {
          items: [
            {quantity: 10n, metadata: {order_id: 12345n}},
            {quantity: 20n, metadata: null},
          ],
        };
        const result = coerceV2RequestData(input, schema);
        expect(result).to.deep.equal({
          items: [
            {quantity: '10', metadata: {order_id: '12345'}},
            {quantity: '20', metadata: null},
          ],
        });
      });
    });
  });

  describe('coerceV2ResponseData', () => {
    describe('int64_string kind', () => {
      const schema: V2RuntimeSchema = {kind: 'int64_string'};

      it('converts string to bigint', () => {
        expect(coerceV2ResponseData('42', schema)).to.equal(42n);
      });

      it('converts large string to bigint', () => {
        expect(coerceV2ResponseData('9007199254740991', schema)).to.equal(
          9007199254740991n
        );
      });

      it('converts zero string to bigint', () => {
        expect(coerceV2ResponseData('0', schema)).to.equal(0n);
      });

      it('converts negative string to bigint', () => {
        expect(coerceV2ResponseData('-100', schema)).to.equal(-100n);
      });

      it('leaves non-string values unchanged', () => {
        expect(coerceV2ResponseData(42, schema)).to.equal(42);
      });

      it('passes null through', () => {
        expect(coerceV2ResponseData(null, schema)).to.equal(null);
      });

      it('passes undefined through', () => {
        expect(coerceV2ResponseData(undefined, schema)).to.equal(undefined);
      });
    });

    describe('object kind', () => {
      const schema: V2RuntimeSchema = {
        kind: 'object',
        fields: {
          amount: {kind: 'int64_string'},
        },
      };

      it('coerces fields listed in schema', () => {
        const data = {amount: '100'};
        const result = coerceV2ResponseData(data, schema);
        expect(result).to.deep.equal({amount: 100n});
      });

      it('preserves fields not in schema', () => {
        const data = {amount: '100', name: 'test'};
        const result = coerceV2ResponseData(data, schema);
        expect(result).to.deep.equal({amount: 100n, name: 'test'});
      });

      it('mutates in-place', () => {
        const data = {amount: '100'};
        const result = coerceV2ResponseData(data, schema);
        expect(result).to.equal(data);
